
% --- Open the figure (without displaying it)
H_fig = openfig('bode_q1.fig') %[output:40f57330]
% --- Find all axes in the figure
ax = findall(H_fig, 'type', 'axes');

% --- Locate the magnitude axis
for i = 1:length(ax)
    ylabel_text = get(get(ax(i), 'YLabel'), 'String');
    if contains(lower(ylabel_text), 'mag')
        mag_ax = ax(i);
        break;
% --- Parameter search setup (Refined for better results) ---

    end
end

% --- Get magnitude curve data from the loaded figure ---
lines = findall(mag_ax, 'type', 'line');
% --- MODIFICATION 1: Get w_full_range directly from the figure ---
w_full_range = get(lines(1), 'XData'); 
mag_data  = get(lines(1), 'YData');
close(H_fig); % Close the invisible figure

% --- MODIFICATION 2: Use this vector for fitting ---
freq_fit_range = w_full_range; % Frequencies for error calculation
mag_fit_range  = mag_data;  % Magnitudes for error calculation

% --- Parameter search setup (Refined for better results) ---


best_mse = inf;
best_params = [NaN NaN NaN];

wn_range = 4.3:0.05:4.7;
K_range = 0.5:0.05:0.8;
zeta_range = 0.1:0.001:0.12;


% --- Create the new plot figure ---
figure; %[output:8011a5e8]
hold on;  %[output:8011a5e8]
grid on; % <-- Typo fixed %[output:8011a5e8]

% --- Brute-force parameter sweep ---
fprintf('Starting parameter sweep...\n'); %[output:9680d9ee]
for wn = wn_range
    for zeta = zeta_range
        for K = K_range
            % --- Define the transfer function ---
            num = K * wn^2;
            den = [1, 2*zeta*wn, wn^2, 0];
            sys = tf(num, den);

            % --- A) Calculate model magnitude for MSE (using the fig's freq vector) ---
            [mag_for_mse, ~] = bode(sys, freq_fit_range);
            mag_db_for_mse = 20*log10(squeeze(mag_for_mse));
            
            % --- Compute MSE with measured data (Core MATLAB way) ---
            error_squared = (mag_db_for_mse - mag_fit_range).^2;
            mse = mean(error_squared(~isnan(error_squared)));

            % --- B) Calculate model magnitude for PLOTTING (using the fig's freq vector) ---
            [mag_for_plot, ~] = bode(sys, w_full_range);
            mag_db_for_plot = 20*log10(squeeze(mag_for_plot));
            
            % --- Plot the sweep inside this loop for efficiency ---
            plot(w_full_range, mag_db_for_plot, 'Color', [0.85 0.85 0.85]); %[output:8011a5e8]

            % --- Keep best fit ---
            if mse < best_mse
                best_mse = mse;
                best_params = [K, zeta, wn];
            end
        end
    end
end
fprintf('Parameter sweep finished.\n'); %[output:1e72fa6c]

% --- Get best parameters ---
K_best = best_params(1);
zeta_best = best_params(2);
wn_best = best_params(3);

fprintf('Best fit parameters:\n'); %[output:4f43813f]
fprintf('  K     = %.4f\n', K_best); %[output:202dc45c]
fprintf('  zeta  = %.4f\n', zeta_best); %[output:585069f7]
fprintf('  wn    = %.4f rad/s\n', wn_best); %[output:6d0703ba]
fprintf('  MSE   = %.6f\n', best_mse); %[output:41787809]

% --- Generate the final best-fit model response over the FULL range ---
best_sys = tf(K_best * wn_best^2, [1, 2*zeta_best*wn_best, wn_best^2, 0]);
[mag_best, ~] = bode(best_sys, w_full_range);
model_mag_db_best = 20*log10(squeeze(mag_best));

% --- Overlay measured and best-fit curves ---
h_sweeps = findall(gca, 'Color', [0.85 0.85 0.85]);
h_measured = plot(freq_fit_range, mag_fit_range, 'b', 'LineWidth', 2.5); % Measured data %[output:8011a5e8]
h_best_fit = plot(w_full_range, model_mag_db_best, 'r--', 'LineWidth', 2); % Best-fit model %[output:8011a5e8]

% --- Final plot formatting ---
set(gca, 'XScale', 'log'); % Set the x-axis to log scale %[output:8011a5e8]
xlim([1e-1 1e2]);          % Set frequency range from 0.1 to 100 rad/s %[output:8011a5e8]
ylim([-60, 40]);           % Adjust y-limit to match original plot %[output:8011a5e8]
xlabel('Frequency (rad/s)'); %[output:8011a5e8]
ylabel('Magnitude (dB)'); %[output:8011a5e8]
title('Bode Magnitude: Model Fit vs Measured Data'); %[output:8011a5e8]
legend([h_sweeps(1), h_measured, h_best_fit], ... %[output:8011a5e8]
       'Model sweeps', 'Measured data', 'Best-fit model', 'Location', 'southwest'); %[output:8011a5e8]
set(gca, 'FontSize', 12, 'LineWidth', 1.2); %[output:8011a5e8]
hold off; %[output:8011a5e8]

